import click
from enum import Enum

class Color(Enum):
    RED = 'red'
    BLUE = 'blue'

# In 8.3.3, non-basic flag_value types were stringified without explicit type=UNPROCESSED
@click.command()
@click.option('--color', flag_value=Color.RED)
def cmd(color):
    # color would be stringified to "Color.RED" string
    assert isinstance(color, str)

if __name__ == '__main__':
    cmd()
